def carry_states(apps, schema_editor):
    """Assets take the state their history already says (17 October 2026): one
    disposed is out of the register, one proposed waits for DPFPA, one with an
    unfinished repair is under repair."""
    Asset = apps.get_model('attendance', 'Asset')
    AssetDisposal = apps.get_model('attendance', 'AssetDisposal')
    AssetMaintenance = apps.get_model('attendance', 'AssetMaintenance')
    for disposal in AssetDisposal.objects.all():
        disposal.quantity = Asset.objects.get(pk=disposal.asset_id).quantity
        disposal.save(update_fields=['quantity'])
    Asset.objects.filter(id__in=AssetMaintenance.objects.exclude(status='completed').values('asset_id')
                         ).update(status='under_repair')
    Asset.objects.filter(id__in=AssetDisposal.objects.filter(status='proposed').values('asset_id')
                         ).update(status='pending_disposal')
    Asset.objects.filter(id__in=AssetDisposal.objects.filter(status='disposed').values('asset_id')
                         ).update(status='disposed')


